package communication;import codec.ByteStreamDecoder;import codec.lvtojava.LVTypeDecoder;import jakarta.servlet.ServletInputStream;import jakarta.servlet.http.HttpServlet;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import types.labview.LVTypeDescriptor;import java.io.IOException;public class HTTPListener extends HttpServlet {        /**         * @param args         */        public static void main(String[] args) {        }        public void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {            ServletInputStream reader = request.getInputStream();            byte[] message = reader.readAllBytes();            ByteStreamDecoder byteStreamDecoder = new ByteStreamDecoder(message);            byteStreamDecoder.decode();        }}